import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"プライバシーの選択肢","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-choices.md","filePath":"ja/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`ja/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="プライバシーの選択肢" tabindex="-1">プライバシーの選択肢 <a class="header-anchor" href="#プライバシーの選択肢" aria-label="Permalink to “プライバシーの選択肢”">​</a></h1><p>Sudoku は、データの取り扱いを最小限に抑えたオフラインファーストのアプリです。本ページでは、プライバシーに関する選択肢と、データを管理する方法について説明します。</p><h2 id="データは-既定で-お使いのデバイス内に留まります" tabindex="-1">データは（既定で）お使いのデバイス内に留まります <a class="header-anchor" href="#データは-既定で-お使いのデバイス内に留まります" aria-label="Permalink to “データは（既定で）お使いのデバイス内に留まります”">​</a></h2><ul><li>設定、ゲームの状態、鉛筆メモ、統計などのすべてのゲームデータは、既定でお使いのデバイス内にローカル保存されます。</li><li>中核となるゲームプレイにネットワークアクセスは一切不要です。</li><li>広告、分析、トラッキングはありません。</li></ul><h2 id="任意のクラウド機能" tabindex="-1">任意のクラウド機能 <a class="header-anchor" href="#任意のクラウド機能" aria-label="Permalink to “任意のクラウド機能”">​</a></h2><h3 id="icloud-同期" tabindex="-1">iCloud 同期 <a class="header-anchor" href="#icloud-同期" aria-label="Permalink to “iCloud 同期”">​</a></h3><p>iCloud 同期を有効にした場合：</p><ul><li>データは<strong>お客様個人の iCloud アカウント</strong>にのみ同期され、当社が管理するサーバーには同期されません。</li><li>転送時および保存時の暗号化は Apple の CloudKit が処理します。</li><li>いつでも無効にできます：設定 → [あなたの名前] → iCloud → iCloud を使用する App → Sudoku をオフにする。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Game Center を利用する場合：</p><ul><li>リーダーボードのスコアが、Game Center の表示名で公開される場合があります。</li><li>実績の進捗は Game Center によって記録されます。</li><li>設定で Game Center からサインアウトすると無効にできます。</li></ul><h2 id="クラウド以外でネットワークを使う唯一の機能-「more-apps」" tabindex="-1">クラウド以外でネットワークを使う唯一の機能：「More Apps」 <a class="header-anchor" href="#クラウド以外でネットワークを使う唯一の機能-「more-apps」" aria-label="Permalink to “クラウド以外でネットワークを使う唯一の機能：「More Apps」”">​</a></h2><p>他にネットワークへアクセスするのは、設定内の任意の <strong>「More Apps」</strong> セクションのみで、姉妹アプリの一覧を取得します。この機能は：</p><ul><li>個人データを一切送信せず、アプリ名とリンクの一覧を取得するだけです。</li><li>完全に無視してもゲームプレイに影響はありません。</li><li>お客様をトラッキングしたり、識別子を保存したりすることはありません。</li></ul><h2 id="データの消去" tabindex="-1">データの消去 <a class="header-anchor" href="#データの消去" aria-label="Permalink to “データの消去”">​</a></h2><p>デバイスからアプリのデータをすべて削除するには：</p><ul><li><strong>iPhone/iPad</strong>：アプリを削除して再インストールします</li><li><strong>Mac</strong>：Sudoku を終了してから、コンテナを削除します：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>iCloud で同期されたデータもあわせて消去するには：</p><ol><li><strong>設定 → [あなたの名前] → iCloud → アカウントのストレージを管理</strong> に移動します</li><li>アプリ一覧から Sudoku を探します</li><li><strong>データを削除</strong> をタップします</li></ol><p>これにより、設定、統計、ゲームのセーブデータ、デイリーチャレンジの進捗がすべて iCloud から完全に削除されます。</p><h2 id="トラッキングなし、広告なし" tabindex="-1">トラッキングなし、広告なし <a class="header-anchor" href="#トラッキングなし、広告なし" aria-label="Permalink to “トラッキングなし、広告なし”">​</a></h2><p>Sudoku には、広告、分析、トラッキングピクセル、サードパーティとのデータ共有連携が一切含まれていません。本アプリはゲームプレイにネットワークアクセスを必要としません。</p><h2 id="プライバシーに関するご請求の概要" tabindex="-1">プライバシーに関するご請求の概要 <a class="header-anchor" href="#プライバシーに関するご請求の概要" aria-label="Permalink to “プライバシーに関するご請求の概要”">​</a></h2><table tabindex="0"><thead><tr><th>ご請求</th><th>必須か</th><th>内容</th></tr></thead><tbody><tr><td>ローカル保存</td><td>必須（自動）</td><td>ゲームデータをデバイス内に保存します</td></tr><tr><td>iCloud 同期</td><td>任意</td><td>CloudKit を通じてデバイス間でデータを同期します</td></tr><tr><td>Game Center</td><td>任意</td><td>リーダーボードと実績</td></tr><tr><td>ネットワーク（「More Apps」）</td><td>任意</td><td>姉妹アプリの一覧を取得します</td></tr></tbody></table><p>個人データを収集したり、当社が管理するサーバーへ送信したりすることはないため、アクセス・削除・移行の対象となる中央データベースは存在しません。すべてのデータはローカルに保存されるか、Apple のサービス（iCloud／Game Center）によって管理されます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to “お問い合わせ”">​</a></h2><p>本手続きについてご不明な点がある場合は、<code>https://github.com/sudoku-pro/sudoku-site/issues</code> で issue を作成するか、sudoku@w3cub.com までメールでお問い合わせください。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};